	var _ reviewtypes.Sink = review.SynthesisSink{}
}

// TestSynthesisSink_AgentEventIsNoOp verifies AgentEvent produces no output.
func TestSynthesisSink_AgentEventIsNoOp(t *testing.T) {
	t.Parallel()
	w := &bytes.Buffer{}
