225	type streamCloseReason int
226	
227	const (
228		streamCloseTransport streamCloseReason = iota // network/transport error
229		streamCloseReconnect                          // server `event: reconnect`
230		streamCloseForbidden                          // server `event: forbidden`
231		streamCloseError                              // server `event: error`
232		streamCloseDone                               // context cancellation
233		streamCloseTerminal                           // non-recoverable HTTP status (401/403/404/410)
234	)
235	
236	// terminalHTTPStatuses are HTTP response codes for which retrying the SSE
237	// stream cannot succeed: auth failures (401/403) and resource-not-found-style
238	// errors (404/410). 429 is intentionally *not* terminal — it's a transient
239	// rate-limit signal that should back off and retry.
240	var terminalHTTPStatuses = [...]int{
241		http.StatusUnauthorized, // 401
242		http.StatusForbidden,    // 403
243		http.StatusNotFound,     // 404
244		http.StatusGone,         // 410
245	}
246	
247	func isTerminalHTTPError(err error) bool {
248		for _, code := range terminalHTTPStatuses {
249			if api.IsHTTPErrorStatus(err, code) {
250				return true
251			}
252		}
253		return false
254	}
255	
256	// streamOnce opens a single SSE connection, prints events until it closes for
257	// any reason, and returns the close reason plus the last `id:` observed (so
258	// the caller can pass it as `Last-Event-ID` on reconnect).
259	//
260	//nolint:cyclop,gocognit // SSE framing parser is naturally branchy; splitting hurts readability
261	func streamOnce(
262		ctx context.Context,
263		client *api.Client,
264		path string,
265		lastEventID string,
266		jsonOutput, showPings bool,
267		w, errW io.Writer,
268	) (streamCloseReason, string, error) {
269		headers := http.Header{}
270		headers.Set("Accept", "text/event-stream")
271		headers.Set("Cache-Control", "no-cache")
272		if lastEventID != "" {
273			headers.Set("Last-Event-ID", lastEventID)
274		}
275	
276		resp, err := client.GetStream(ctx, path, headers)
277		if err != nil {
278			return streamCloseTransport, "", fmt.Errorf("open SSE stream: %w", err)
279		}
280		defer resp.Body.Close()
281	
282		if err := checkTrailResponse(resp); err != nil {
283			// Terminal: surface the error and don't reconnect. 429 deliberately
284			// falls through to streamCloseTransport so the caller backs off.
285			if isTerminalHTTPError(err) {
286				return streamCloseTerminal, "", err
287			}
288			return streamCloseTransport, "", err
289		}
290	
291		scanner := bufio.NewScanner(resp.Body)
292		// SSE frames can be larger than the default 64KiB scanner buffer when a
293		// review event carries long comment bodies; bump to 1 MiB to match the API's
294		// per-comment limits.
295		scanner.Buffer(make([]byte, 0, 64*1024), 1<<20)
296	
297		var (
298			eventName  string
299			dataLines  []string
300			eventID    string // id of the in-progress frame (reset on flush)
301			lastSeenID string // most recent SSE id from any frame that includes one
302		)
303	
304		flush := func() (streamCloseReason, bool) {
305			defer func() {
306				eventName = ""
307				dataLines = nil
308				eventID = ""
309			}()
310			if eventName == "" && len(dataLines) == 0 {
311				return streamCloseTransport, false
312			}
313			data := strings.Join(dataLines, "\n")
314			printSSEEvent(w, errW, eventName, data, jsonOutput)
315	
316			if eventID != "" {
317				lastSeenID = eventID
318			}
319	
320			switch eventName {
321			case sseEventReconnect:
322				return streamCloseReconnect, true
323			case sseEventForbidden:
324				return streamCloseForbidden, true
325			case sseEventError:
326				return streamCloseError, true
327			}
328			return streamCloseTransport, false
329		}
330	
331		for scanner.Scan() {
332			line := scanner.Text()
333	
334			// Blank line dispatches the event.
335			if line == "" {
336				if reason, done := flush(); done {
337					return reason, lastSeenID, nil
338				}
339				continue
340			}
341	
342			// Comment / keepalive line.
343			if strings.HasPrefix(line, ":") {
344				if showPings {
345					fmt.Fprintln(errW, "ping:", strings.TrimSpace(strings.TrimPrefix(line, ":")))
346				}
347				continue
348			}
349	
350			field, value, ok := strings.Cut(line, ":")
351			if !ok {
352				// Field-only line (no colon) — per spec the value is empty.
353				field = line
354				value = ""
355			}
356			// Per SSE spec: a single leading space after the colon is ignored.
357			value = strings.TrimPrefix(value, " ")
358	
359			switch field {
360			case "event":
361				eventName = value
362			case "data":
363				dataLines = append(dataLines, value)
364			case "id":
365				eventID = value
366			case "retry":
367				// Ignored — we manage backoff client-side.
368			}
369		}
370	
371		if err := scanner.Err(); err != nil {
372			// Context cancellation surfaces here as a wrapped "context canceled".
373			if errors.Is(err, context.Canceled) || ctx.Err() != nil {
374				return streamCloseDone, lastSeenID, nil
375			}
376			return streamCloseTransport, lastSeenID, fmt.Errorf("read SSE stream: %w", err)
377		}
378		return streamCloseTransport, lastSeenID, nil
379	}
380	
381	// printSSEEvent renders a single SSE event in either human-readable or
382	// json-line form. `data` may be empty (e.g. for the rare frame with only an
383	// `event:` line) — we still print something so the caller sees it.
384	func printSSEEvent(w, errW io.Writer, eventName, data string, jsonOutput bool) {
385		if jsonOutput {
386			// Emit a JSON envelope so consumers can reliably parse with
387			// `jq`/scripts. The data field is preserved verbatim if it isn't
388			// valid JSON; otherwise it's inlined as a sub-object.
389			envelope := map[string]any{"event": eventName}
390			if data != "" {
391				var sub any
392				if err := json.Unmarshal([]byte(data), &sub); err == nil {
393					envelope["data"] = sub
394				} else {
395					envelope["data"] = data
396				}
397			}
398			out, err := json.Marshal(envelope)
399			if err != nil {
400				fmt.Fprintf(errW, "failed to marshal event: %v\n", err)
401				return
402			}
403			fmt.Fprintln(w, string(out))
404			return
405		}
406	
407		switch eventName {
408		case sseEventReady:
409			printReadyEvent(w, data)
410			return
411		case sseEventReconnect:
412			fmt.Fprintln(errW, "↻ server requested reconnect")
413			return
414		case sseEventForbidden:
415			fmt.Fprintln(errW, "✖ stream access revoked")
416			return
417		case sseEventError:
418			printStreamError(errW, data)
419			return
420		}
421	
422		if ev, ok := parseReviewStreamEvent(eventName, data); ok {
423			printReviewStreamEvent(w, ev)
424			return
425		}
426	
427		// Fallback for unknown events or unparseable payloads: print raw.
428		fmt.Fprintf(w, "%s: %s\n", eventName, truncateForLog(data, 500))
429	}
430	
431	type reviewReadyPayload struct {
432		TrailID string `json:"trail_id"`
433		Cursor  int    `json:"cursor"`
434	}
435	
436	type reviewStreamEvent struct {
437		ID              any            `json:"id"`
438		TrailID         string         `json:"trail_id"`
439		ReviewSessionID *string        `json:"review_session_id"`
440		ActorID         string         `json:"actor_id"`
441		EventType       string         `json:"event_type"`
442		TargetType      string         `json:"target_type"`
443		TargetID        string         `json:"target_id"`
444		Payload         map[string]any `json:"payload"`
445		CreatedAt       time.Time      `json:"created_at"`
446	}
447	
448	func printReadyEvent(w io.Writer, data string) {
449		var p reviewReadyPayload
450		if err := json.Unmarshal([]byte(data), &p); err == nil {
451			parts := []string{"● connected"}
452			if p.TrailID != "" {
453				parts = append(parts, "to trail "+p.TrailID)
454			}
455			if p.Cursor > 0 {
456				parts = append(parts, fmt.Sprintf("after event %d", p.Cursor))
457			}
458			fmt.Fprintln(w, strings.Join(parts, " "))
459			return
460		}
461		fmt.Fprintf(w, "ready: %s\n", truncateForLog(data, 500))
462	}
463	
464	func printStreamError(errW io.Writer, data string) {
465		var p struct {
466			Message string `json:"message"`
467		}
468		if jerr := json.Unmarshal([]byte(data), &p); jerr != nil {
469			// Best-effort: server payload may be missing or malformed; we still
470			// want to surface that an error event arrived.
471			fmt.Fprintf(errW, "Warning: malformed error payload: %v\n", jerr)
472		}
473		if p.Message != "" {
474			fmt.Fprintf(errW, "✖ stream error: %s\n", p.Message)
475		} else {
476			fmt.Fprintln(errW, "✖ stream error")
477		}
478	}
479	
480	func parseReviewStreamEvent(eventName, data string) (reviewStreamEvent, bool) {
481		var ev reviewStreamEvent
482		if err := json.Unmarshal([]byte(data), &ev); err != nil {
483			return ev, false
484		}
485		if ev.EventType == "" {
486			ev.EventType = eventName
487		}
488		if ev.EventType == "" && ev.TargetType == "" && ev.TargetID == "" {
489			return ev, false
490		}
491		return ev, true
492	}
493	
494	func printReviewStreamEvent(w io.Writer, ev reviewStreamEvent) {
495		prefix := ""
496		if !ev.CreatedAt.IsZero() {
497			prefix = "[" + ev.CreatedAt.Local().Format("15:04:05") + "] "
498		}
499		actor := ev.ActorID
500		if actor == "" {
501			actor = "unknown actor"
502		}
503	
504		switch ev.EventType {
505		case "code_version.created":
506			fmt.Fprintf(w, "%scode version %s created (head %s)\n", prefix, ev.TargetID, payloadString(ev.Payload, "head_sha"))
507		case "code_version.base_sha_set":
508			fmt.Fprintf(w, "%scode version %s base set to %s\n", prefix, ev.TargetID, payloadString(ev.Payload, "base_sha"))
509		case "session.started":
510			fmt.Fprintf(w, "%ssession started by %s (code version %s)\n", prefix, actor, payloadString(ev.Payload, "code_version_id"))
511		case "session.ended":
512			reason := payloadString(ev.Payload, "reason")
513			if reason != "" {
514				fmt.Fprintf(w, "%ssession ended by %s (%s)\n", prefix, actor, reason)
515			} else {
516				fmt.Fprintf(w, "%ssession ended by %s\n", prefix, actor)
517			}
518		case "comment.created":
519			file := payloadString(ev.Payload, "file_path")
520			severity := payloadString(ev.Payload, "severity")
521			switch {
522			case file != "" && severity != "":
523				fmt.Fprintf(w, "%sfinding created by %s on %s (%s) — %s\n", prefix, actor, file, severity, ev.TargetID)
524			case file != "":
525				fmt.Fprintf(w, "%sfinding created by %s on %s — %s\n", prefix, actor, file, ev.TargetID)
526			default:
527				fmt.Fprintf(w, "%sfinding created by %s — %s\n", prefix, actor, ev.TargetID)
528			}
529		case "comment.status_changed":
530			fmt.Fprintf(w, "%sfinding %s status %s → %s\n", prefix, ev.TargetID, payloadString(ev.Payload, "from"), payloadString(ev.Payload, "to"))
531		case "comment.updated":
532			fmt.Fprintf(w, "%sfinding %s updated by %s\n", prefix, ev.TargetID, actor)
533		case "comment.stale_checked":
534			fmt.Fprintf(w, "%sfinding %s marked %s (%s)\n", prefix, ev.TargetID, payloadString(ev.Payload, "outcome"), payloadString(ev.Payload, "reason"))
535		case "suggested_change.created":
536			fmt.Fprintf(w, "%ssuggested change %s created for finding %s (%s)\n", prefix, ev.TargetID, payloadString(ev.Payload, "review_comment_id"), payloadString(ev.Payload, "change_type"))
537		case "suggested_change.updated":
538			fmt.Fprintf(w, "%ssuggested change %s updated by %s\n", prefix, ev.TargetID, actor)
539		case "suggested_change.check_result", "suggested_change.apply_result":
540			fmt.Fprintf(w, "%s%s for %s: %s\n", prefix, ev.EventType, payloadString(ev.Payload, "suggested_change_id"), payloadString(ev.Payload, "status"))
541		case "thread.created":
542			fmt.Fprintf(w, "%sthread %s created for finding %s\n", prefix, ev.TargetID, payloadString(ev.Payload, "review_comment_id"))
543		case "thread.message_added":
544			fmt.Fprintf(w, "%sthread message %s added by %s\n", prefix, ev.TargetID, actor)
545		case "thread.message_edited":
546			fmt.Fprintf(w, "%sthread message %s edited by %s\n", prefix, ev.TargetID, actor)
547		case "comment.linked":
548			fmt.Fprintf(w, "%sfinding link created: %s → %s\n", prefix, payloadString(ev.Payload, "source_comment_id"), payloadString(ev.Payload, "target_comment_id"))
549		case "comment.unlinked":
550			fmt.Fprintf(w, "%sfinding link removed: %s → %s\n", prefix, payloadString(ev.Payload, "source_comment_id"), payloadString(ev.Payload, "target_comment_id"))
551		default:
552			fmt.Fprintf(w, "%s%s %s/%s by %s\n", prefix, ev.EventType, ev.TargetType, ev.TargetID, actor)
553		}
554	}
555	
556	func payloadString(payload map[string]any, key string) string {
557		if payload == nil {
558			return ""
559		}
560		v, ok := payload[key]
561		if !ok || v == nil {
562			return ""
563		}
564		switch t := v.(type) {
565		case string:
566			return t
567		case fmt.Stringer:
568			return t.String()
569		default:
570			return fmt.Sprint(t)
571		}
572	}
573	
574	// truncateForLog clips body text on a rune boundary so a single multi-line
575	// payload doesn't blow up the watch view. Newlines collapse to spaces.
576	func truncateForLog(s string, maxRunes int) string {
577		s = strings.ReplaceAll(s, "\r\n", " ")
578		s = strings.ReplaceAll(s, "\n", " ")
579		rs := []rune(s)
580		if len(rs) <= maxRunes {
581			return s
582		}
583		return string(rs[:maxRunes]) + "…"
584	}
